import { FormEvent, ReactNode, useEffect, useState } from "react";
import { Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from "react-router-dom";
import { api } from "./api";
import { APP_PATHS, humanizeRole, humanizeStatus, visibleAppRoutes } from "./appRoutes";
import { ActivatePage, ForgotPasswordPage, InvitePage, MemberLogin, PermissionRoute, ProtectedRoute, ResetPasswordPage, UnauthorizedPage } from "./AuthPages";
import { HowItWorks, PublicAbout, PublicContact, PublicFaq, PublicHome, PublicImpactDetail, PublicImpactIndex, PublicLayout, PublicSafety } from "./PublicSite";
import type { Cluster, ImpactProject, Research, User } from "./types";
import { GlobalUtilities } from "./ui";

function StatusBadge({ children }: { children: ReactNode }) {
  return <span className="status-badge">{humanizeStatus(String(children))}</span>;
}

function ErrorBox({ error }: { error: unknown }) {
  if (!error) return null;
  return <div className="notice danger">{error instanceof Error ? error.message : "Something went wrong."}</div>;
}

function Loading() {
  return <div className="loading"><span className="spinner" /> Loading workspace…</div>;
}

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [checking, setChecking] = useState(true);
  useEffect(() => {
    api.me().then(setUser).catch(() => setUser(null)).finally(() => setChecking(false));
  }, []);
  const publicPage = (page: ReactNode) => <PublicLayout user={user}>{page}</PublicLayout>;
  return <><GlobalUtilities user={user} /><Routes>
    <Route path="/" element={publicPage(<PublicHome user={user} />)} />
    <Route path="/about" element={publicPage(<PublicAbout />)} />
    <Route path="/how-it-works" element={publicPage(<HowItWorks />)} />
    <Route path="/impact" element={publicPage(<PublicImpactIndex />)} />
    <Route path="/impact/:slug" element={publicPage(<PublicImpactDetail />)} />
    <Route path="/safety-and-privacy" element={publicPage(<PublicSafety />)} />
    <Route path="/faq" element={publicPage(<PublicFaq />)} />
    <Route path="/contact" element={publicPage(<PublicContact />)} />
    <Route path="/login" element={<MemberLogin user={user} onLogin={setUser} />} />
    <Route path="/activate" element={<ActivatePage />} />
    <Route path="/register" element={<Navigate to="/activate" replace />} />
    <Route path="/invite/:token" element={<InvitePage onLogin={setUser} />} />
    <Route path="/forgot-password" element={<ForgotPasswordPage />} />
    <Route path="/reset-password/:token" element={<ResetPasswordPage />} />
    <Route path="/verify-email" element={<ActivatePage verificationOnly />} />
    <Route path="/unauthorized" element={<UnauthorizedPage />} />
    <Route path="/app/*" element={<ProtectedRoute user={user} checking={checking}>{user ? <PermissionRoute user={user} permission="app.access"><Shell user={user} onLogout={() => setUser(null)} /></PermissionRoute> : null}</ProtectedRoute>} />
    <Route path="/dashboard" element={<Navigate to="/app/dashboard" replace />} />
    <Route path="/problems/*" element={<Navigate to="/app/problems" replace />} />
    <Route path="/research/*" element={<Navigate to="/app/research" replace />} />
    <Route path="/projects/*" element={<Navigate to="/app/projects" replace />} />
    <Route path="/tasks" element={<Navigate to="/app/tasks" replace />} />
    <Route path="/notifications" element={<Navigate to="/app/notifications" replace />} />
    <Route path="/mentor" element={<Navigate to="/app/mentor" replace />} />
    <Route path="/osis" element={<Navigate to="/app/osis" replace />} />
    <Route path="/moderation" element={<Navigate to="/app/moderation" replace />} />
    <Route path="/admin/*" element={<Navigate to="/app/admin" replace />} />
    <Route path="/help" element={<Navigate to="/safety-and-privacy" replace />} />
    <Route path="*" element={publicPage(<div className="public-empty public-not-found"><h1>That page does not exist.</h1><p>Return to the Pilar Impact Lab homepage or sign in to the member workspace.</p><Link className="public-button primary" to="/">Return home</Link></div>)} />
  </Routes></>;
}

function Shell({ user, onLogout }: { user: User; onLogout: () => void }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [logoutError, setLogoutError] = useState<unknown>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [activeWorkspace, setActiveWorkspace] = useState(() => localStorage.getItem("impactos_active_workspace") || user.roles?.[0] || user.role);
  const demoMode = import.meta.env.DEV && (import.meta.env.VITE_APP_MODE || "DEMO") === "DEMO";
  const permissions = new Set(user.permissions || []);
  const navItems = visibleAppRoutes([...permissions]);
  const selectWorkspace = (workspace: string) => { setActiveWorkspace(workspace); localStorage.setItem("impactos_active_workspace", workspace); navigate(APP_PATHS.dashboard); };
  const logout = async () => { try { await api.logout(); onLogout(); } catch (err) { setLogoutError(err); } };
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen ? "mobile-open" : ""}`}><Link to={APP_PATHS.dashboard} className="brand" onClick={() => setMobileOpen(false)}><span className="brand-mark">i</span><span><strong>ImpactOS</strong><small>Pilar Impact Lab</small></span></Link><div className="sidebar-section">WORKSPACE</div><nav>{navItems.map((item) => <Link key={item.id} className={location.pathname === item.path || location.pathname.startsWith(`${item.path}/`) ? "active" : ""} to={item.path} onClick={() => setMobileOpen(false)}><span aria-hidden="true">{item.icon}</span> {item.label}</Link>)}</nav><div className="sidebar-foot"><div className="private-note">🔒 Private by design<br /><span>Decisions stay with people.</span></div><button className="logout-link" onClick={logout}>Sign out</button></div></aside>
    <div className="main-area"><header className="topbar"><button className="mobile-menu-button" onClick={() => setMobileOpen((open) => !open)} aria-label={mobileOpen ? "Close navigation" : "Open navigation"}>☰</button><div className="breadcrumbs">Pilar Impact Lab <span>/</span> {labelFor(location.pathname)}</div><div className="top-actions">{demoMode && <span className="demo-pill">DEMO DATA</span>}{(user.roles || []).length > 1 && <select className="workspace-switcher" aria-label="Active workspace" value={activeWorkspace} onChange={(event) => selectWorkspace(event.target.value)}>{user.roles?.map((role) => <option key={role} value={role}>{humanizeRole(role)}</option>)}</select>}<span className="role-chip">{user.display_name} · {humanizeRole(activeWorkspace)}</span><button className="icon-button" onClick={() => navigate(APP_PATHS.notifications)} aria-label="Notifications">◌</button></div></header><div className="mode-strip">{demoMode ? "Closed-alpha mode · synthetic data only · " : "Member workspace · "}<Link to="/safety-and-privacy">Need help or safeguarding support?</Link></div><main className="content"><ErrorBox error={logoutError} /><Routes>
      <Route path="/app/dashboard" element={<PhaseOneDashboard user={user} activeWorkspace={activeWorkspace} />} />
      <Route path="/app" element={<Navigate to={APP_PATHS.dashboard} replace />} />
      <Route path="/app/problems" element={<Problems />} />
      <Route path="/app/problems/new" element={<NewProblem />} />
      <Route path="/app/problems/:clusterId" element={<ClusterDetail user={user} />} />
      <Route path="/app/reports" element={<MyReportsPage />} />
      <Route path="/app/reports/:reportId" element={<MyReportDetailPage />} />
      <Route path="/app/research" element={<ResearchList />} />
      <Route path="/app/research/:researchId" element={<ResearchPage user={user} />} />
      <Route path="/app/projects" element={<ImpactList />} />
      <Route path="/app/projects/:projectId" element={<ImpactPage user={user} />} />
      <Route path="/app/profile" element={<PermissionRoute user={user} permission="profile.read_own"><ProfilePage user={user} /></PermissionRoute>} />
      <Route path="/app/mentor" element={<PermissionRoute user={user} permission="mentor.review"><MentorPage /></PermissionRoute>} />
      <Route path="/app/mentor/reviews" element={<PermissionRoute user={user} permission="mentor.review"><MentorPage /></PermissionRoute>} />
      <Route path="/app/mentor/reviews/:reviewId" element={<PermissionRoute user={user} permission="mentor.review"><ResearchPage user={user} /></PermissionRoute>} />
      <Route path="/app/osis" element={<PermissionRoute user={user} permission="osis.review"><OsisPage /></PermissionRoute>} />
      <Route path="/app/osis/priorities" element={<PermissionRoute user={user} permission="osis.priority_manage"><OsisPrioritiesPage /></PermissionRoute>} />
      <Route path="/app/moderation" element={<PermissionRoute user={user} permission="moderation.review"><ModerationPage /></PermissionRoute>} />
      <Route path="/app/moderation/reports" element={<PermissionRoute user={user} permission="moderation.review"><ModerationPage /></PermissionRoute>} />
      <Route path="/app/moderation/reports/:reportId" element={<PermissionRoute user={user} permission="moderation.review"><ModerationReportPage /></PermissionRoute>} />
      <Route path="/app/admin" element={<Navigate to="/app/admin/members" replace />} />
      <Route path="/app/admin/members" element={<PermissionRoute user={user} permission="admin.members.read"><AdminMembersPage /></PermissionRoute>} />
      <Route path="/app/admin/invitations" element={<PermissionRoute user={user} permission="admin.invitations.manage"><AdminInvitationsPage /></PermissionRoute>} />
      <Route path="/app/admin/audit" element={<PermissionRoute user={user} permission="admin.audit.read"><AdminAuditPage /></PermissionRoute>} />
      <Route path="/app/admin/feedback" element={<PermissionRoute user={user} permission="admin.feedback.read"><AdminFeedbackPage /></PermissionRoute>} />
      <Route path="/app/admin/legacy" element={<PermissionRoute user={user} permission="admin.members.manage"><AdminPage /></PermissionRoute>} />
      <Route path="/app/notifications" element={<NotificationsPage />} />
      <Route path="/app/tasks" element={<PermissionRoute user={user} permission="task.read_assigned"><TasksPage /></PermissionRoute>} />
      <Route path="/app/unauthorized" element={<UnauthorizedPage />} />
      <Route path="/app/help" element={<HelpPage />} />
      <Route path="*" element={<NotFound />} />
    </Routes></main></div>
  </div>;
}

function labelFor(path: string) { if (path.includes("problems")) return "Problems"; if (path.includes("research")) return "Research"; if (path.includes("projects")) return "Impact projects"; if (path.includes("mentor")) return "Mentor review"; if (path.includes("moderation")) return "Moderation"; if (path.includes("osis")) return "OSIS"; if (path.includes("admin")) return "Admin"; return "Dashboard"; }

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>; }

function DashboardItem({ item }: { item: any }) {
  const content = <><div><strong>{item.title}</strong>{item.detail && <p>{item.detail}</p>}</div>{item.status && <StatusBadge>{item.status}</StatusBadge>}</>;
  return item.href ? <Link className="list-row" to={item.href}>{content}<span aria-hidden="true">→</span></Link> : <div className="list-row">{content}</div>;
}

function DashboardSection({ eyebrow, title, items, emptyTitle, emptyDescription, action }: { eyebrow: string; title: string; items: any[]; emptyTitle: string; emptyDescription: string; action?: ReactNode }) {
  return <section className="panel"><div className="panel-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{action}</div>{items.length ? <div className="list-stack">{items.map((item) => <DashboardItem key={item.id} item={item} />)}</div> : <div className="empty-state compact-empty"><h3>{emptyTitle}</h3><p>{emptyDescription}</p></div>}</section>;
}

function PhaseOneDashboard({ user, activeWorkspace }: { user: User; activeWorkspace?: string }) {
  const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null);
  const load = () => { setError(null); setData(null); api.dashboard(activeWorkspace).then(setData).catch(setError); };
  useEffect(() => { load(); }, [activeWorkspace]);
  if (error) return <><PageHeader eyebrow="MEMBER WORKSPACE" title="Your dashboard is unavailable" description="ImpactOS could not load the records for this workspace." /><ErrorBox error={error} /><button className="button primary" onClick={load}>Try again</button></>;
  if (!data) return <Loading />;
  const role = data.viewer.roles.find((item: any) => item.code === data.viewer.active_workspace) || data.viewer.roles[0];
  const sections = data.role_sections || {};
  const action = data.primary_action;
  const myWork = (data.my_work || []).slice(0, 6);
  const attention = (data.attention_items || []).slice(0, 6);
  const roleItems = data.viewer.active_workspace === "STUDENT_CONTRIBUTOR" ? sections.followed_problems || [] : data.viewer.active_workspace === "STUDENT_PROJECT_LEADER" ? [...(sections.research || []), ...(sections.projects || []), ...(sections.tasks || [])] : data.viewer.active_workspace === "MENTOR" ? sections.reviews_awaiting_attention || [] : data.viewer.active_workspace === "OSIS_REVIEWER" ? sections.validated_problems || [] : data.viewer.active_workspace === "MODERATOR" ? [...(sections.new_reports || []), ...(sections.restricted_reports || [])] : [];
  return <><PageHeader eyebrow="MEMBER WORKSPACE" title={`Good morning, ${data.viewer.display_name}.`} description={data.viewer.responsibility} action={<Link className="button primary" to={action.href}>{action.label}</Link>} />
    <div className="hero-card"><div><span className="eyebrow">{data.viewer.school.name}</span><h2>{role?.label || humanizeRole(data.viewer.active_workspace)}</h2><p>{data.synthetic_data ? "This connected scenario is synthetic and exists only for closed-alpha testing." : "Your school workspace is protected and scoped to your active permissions."}</p></div><div className="loop-steps"><span>Observe</span><span>Review</span><span>Act</span><span>Learn</span></div></div>
    <div className="stats-grid compact"><div className="stat-card"><span>Open reports</span><strong>{data.summary.my_open_reports}</strong></div><div className="stat-card"><span>Followed problems</span><strong>{data.summary.followed_problems}</strong></div><div className="stat-card"><span>Incomplete tasks</span><strong>{data.summary.incomplete_tasks}</strong></div><div className="stat-card"><span>Needs attention</span><strong>{data.summary.attention_count}</strong></div></div>
    <div className="two-column"><DashboardSection eyebrow="ATTENTION" title="What needs your attention" items={attention} emptyTitle="Your attention queue is clear." emptyDescription="New work will appear here when a record needs your judgment or a next step." action={<Link className="text-link" to={action.href}>Open primary action</Link>} /><DashboardSection eyebrow="MY WORK" title="Work connected to you" items={myWork} emptyTitle="No active work is assigned yet." emptyDescription="When you submit a concern or join a project, its status and next action will appear here." /></div>
    <div className="two-column"><DashboardSection eyebrow="ROLE VIEW" title={`${role?.label || "Workspace"} overview`} items={roleItems} emptyTitle="This role has no pending records." emptyDescription="The workspace is ready. New authorized records will appear here as the school workflow progresses." /><DashboardSection eyebrow="UPDATES" title="Recent updates" items={(data.recent_updates || []).map((item: any) => ({ ...item, detail: item.message }))} emptyTitle="No updates yet." emptyDescription="Decisions, review notes, and school updates will appear here." /></div>
  </>;
}

function ProfilePage({ user }: { user: User }) {
  return <><PageHeader eyebrow="ACCOUNT" title="Your profile" description="Review the identity and permissions currently attached to this school membership." /><div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">IDENTITY</span><h2>{user.display_name}</h2></div><StatusBadge>{user.status || "ACTIVE"}</StatusBadge></div><div className="detail-list"><div><span>Email</span><strong>{user.email}</strong></div><div><span>School</span><strong>{user.school_name || "Pilar Impact Lab"}</strong></div><div><span>Membership</span><code>{user.membership_id || "—"}</code></div></div></section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">ACCESS</span><h2>Active roles and permissions</h2></div></div><div className="chip-row">{(user.roles?.length ? user.roles : [user.role]).map((role) => <StatusBadge key={role}>{role}</StatusBadge>)}</div><div className="rule-list permission-list">{(user.permissions || []).map((permission) => <span key={permission}>✓ {permission}</span>)}</div></section></div></>;
}

const PHASE_ONE_ROLES = ["STUDENT_CONTRIBUTOR", "STUDENT_PROJECT_LEADER", "MENTOR", "OSIS_REVIEWER", "MODERATOR", "ADMINISTRATOR"];

function AdminMembersPage() {
  const [members, setMembers] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState<string | null>(null);
  const load = () => api.adminMembers().then(setMembers).catch(setError); useEffect(() => { void load(); }, []);
  const updateRoles = async (member: any, value: string) => { setBusy(member.membership_id); setError(null); try { await api.updateMemberRoles(member.membership_id, [value]); await load(); } catch (err) { setError(err); } finally { setBusy(null); } };
  const changeStatus = async (member: any) => { if (member.status === "ACTIVE" && !window.confirm(`Deactivate ${member.email}? This revokes all active sessions.`)) return; setBusy(member.membership_id); setError(null); try { if (member.status === "ACTIVE") await api.deactivateMember(member.membership_id); else await api.reactivateMember(member.membership_id); await load(); } catch (err) { setError(err); } finally { setBusy(null); } };
  return <><PageHeader eyebrow="ADMINISTRATION" title="Members" description="Review school memberships, assign multiple roles, and revoke access when an account is deactivated." /><ErrorBox error={error} /><section className="panel"><div className="table-wrap"><table><thead><tr><th>Member</th><th>Status</th><th>Roles</th><th>Permissions</th><th>Action</th></tr></thead><tbody>{members.map((member) => <tr key={member.id}><td><strong>{member.display_name}</strong><br /><span className="muted">{member.email}</span></td><td><StatusBadge>{member.status}</StatusBadge></td><td><select aria-label={`Role for ${member.email}`} value={member.roles?.[0] || "STUDENT_CONTRIBUTOR"} onChange={(event) => void updateRoles(member, event.target.value)} disabled={busy === member.membership_id}>{PHASE_ONE_ROLES.map((role) => <option key={role} value={role}>{humanizeRole(role)}</option>)}</select>{member.roles?.length > 1 && <small className="muted">+ {member.roles.slice(1).map(humanizeRole).join(", ")}</small>}</td><td><small>{(member.permissions || []).join(", ") || "—"}</small></td><td><button className={`mini-button ${member.status === "ACTIVE" ? "danger-button" : ""}`} onClick={() => void changeStatus(member)} disabled={busy === member.membership_id}>{member.status === "ACTIVE" ? "Deactivate" : "Reactivate"}</button></td></tr>)}</tbody></table></div>{!members.length && !error && <div className="empty-state"><h2>No members found.</h2></div>}</section></>;
}

function AdminInvitationsPage() {
  const [invitations, setInvitations] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState(false); const [activationPath, setActivationPath] = useState(""); const [invite, setInvite] = useState({ email: "", role: "STUDENT_CONTRIBUTOR", expires_in_days: "7" });
  const load = () => api.adminInvitations().then(setInvitations).catch(setError); useEffect(() => { void load(); }, []);
  const create = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(null); try { const result = await api.createInvitation({ email: invite.email, roles: [invite.role], role: invite.role, expires_in_days: Number(invite.expires_in_days) }); setActivationPath(result.activation_path); setInvite((current) => ({ ...current, email: "" })); await load(); } catch (err) { setError(err); } finally { setBusy(false); } };
  const revoke = async (id: string) => { setBusy(true); try { await api.revokeInvitation(id); await load(); } catch (err) { setError(err); } finally { setBusy(false); } };
  const resend = async (id: string) => { setBusy(true); try { const result = await api.resendInvitation(id); setActivationPath(result.activation_path); await load(); } catch (err) { setError(err); } finally { setBusy(false); } };
  return <><PageHeader eyebrow="ADMINISTRATION" title="Invitations" description="Create single-use activation links through the approved school channel. Tokens are shown once and are never stored in plaintext." /><ErrorBox error={error} /><div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">CONTROLLED ACTIVATION</span><h2>Invite a member</h2></div></div><form className="form-grid" onSubmit={create}><label className="wide">School email<input required type="email" value={invite.email} onChange={(event) => setInvite({ ...invite, email: event.target.value })} /></label><label>Role<select value={invite.role} onChange={(event) => setInvite({ ...invite, role: event.target.value })}>{PHASE_ONE_ROLES.map((role) => <option key={role} value={role}>{humanizeRole(role)}</option>)}</select></label><label>Expires in days<input type="number" min="1" max="30" value={invite.expires_in_days} onChange={(event) => setInvite({ ...invite, expires_in_days: event.target.value })} /></label><button className="button primary wide" disabled={busy}>Create invitation</button></form>{activationPath && <div className="notice auth-success"><strong>Copy this activation path once:</strong><br /><code>{activationPath}</code></div>}</section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">INVITATION STATES</span><h2>Recent invitations</h2></div></div><div className="list-stack admin-list">{invitations.map((item) => <div className="list-row" key={item.id}><div><strong>{item.email}</strong><p>{(item.roles || [item.role]).map(humanizeRole).join(" · ")} · {item.state}</p></div><div className="decision-buttons">{item.state === "ACTIVE" && <button className="mini-button" onClick={() => void revoke(item.id)} disabled={busy}>Revoke</button>}{item.state !== "USED" && item.state !== "ACTIVE" && <button className="mini-button" onClick={() => void resend(item.id)} disabled={busy}>Resend</button>}</div></div>)}</div>{!invitations.length && <p className="muted">No invitations yet.</p>}</section></div></>;
}

function AdminAuditPage() {
  const [logs, setLogs] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); useEffect(() => { api.adminAudit().then(setLogs).catch(setError); }, []);
  return <><PageHeader eyebrow="ADMINISTRATION" title="Audit trail" description="Review safe administrative and authentication events without exposing passwords, raw tokens, or sensitive report content." /><ErrorBox error={error} /><section className="panel"><div className="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Request</th><th>Safe metadata</th></tr></thead><tbody>{logs.map((log) => <tr key={log.id}><td>{log.created_at ? new Date(log.created_at).toLocaleString() : "—"}</td><td><strong>{log.action}</strong></td><td>{log.entity_type}<br /><span className="muted">{log.entity_id}</span></td><td><code>{log.request_id || "—"}</code></td><td><code>{JSON.stringify(log.metadata)}</code></td></tr>)}</tbody></table></div>{!logs.length && !error && <div className="empty-state"><h2>No audit events yet.</h2></div>}</section></>;
}

function AdminFeedbackPage() {
  const [items, setItems] = useState<any[]>([]); const [filter, setFilter] = useState("ALL"); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState<string | null>(null);
  const load = () => api.adminFeedback().then(setItems).catch(setError); useEffect(() => { void load(); }, []);
  const update = async (id: string, status: string) => { setBusy(id); setError(null); try { const item = await api.updateFeedback(id, status); setItems((current) => current.map((entry) => entry.id === id ? item : entry)); } catch (err) { setError(err); } finally { setBusy(null); } };
  const visible = filter === "ALL" ? items : items.filter((item) => item.status === filter);
  return <><PageHeader eyebrow="ADMINISTRATION" title="Feedback" description="Review product feedback without exposing private workspace content. Safe context is attached automatically; status changes are recorded in the audit log." /><ErrorBox error={error} /><section className="panel filter-panel"><div className="filter-row"><label>Status<select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="ALL">All feedback</option><option value="NEW">New</option><option value="TRIAGED">Triaged</option><option value="PLANNED">Planned</option><option value="RESOLVED">Resolved</option><option value="CLOSED">Closed</option></select></label><span className="results-count">{visible.length} item{visible.length === 1 ? "" : "s"}</span></div></section><section className="feedback-admin-list">{visible.map((item) => <article className="panel feedback-admin-card" key={item.id}><div className="card-top"><div><span className="eyebrow">{item.category}</span><h2>{item.description}</h2></div><StatusBadge>{item.status}</StatusBadge></div><div className="feedback-meta"><span>{item.severity} severity</span><span>{item.route || "Unknown route"}</span><span>{item.user_role || "Member"}</span><span>{item.created_at ? new Date(item.created_at).toLocaleString() : ""}</span></div><div className="feedback-actions"><label>Update status<select value={item.status} disabled={busy === item.id} onChange={(event) => void update(item.id, event.target.value)}><option value="NEW">New</option><option value="TRIAGED">Triaged</option><option value="PLANNED">Planned</option><option value="RESOLVED">Resolved</option><option value="CLOSED">Closed</option></select></label></div></article>)}{!visible.length && !error && <div className="empty-state"><h2>No feedback in this view.</h2><p>Member feedback will appear here after a submission.</p></div>}</section></>;
}

function Dashboard() {
  const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null);
  useEffect(() => { api.dashboard().then(setData).catch(setError); }, []);
  if (error) return <ErrorBox error={error} />; if (!data) return <Loading />;
  return <><PageHeader eyebrow="OVERVIEW" title="Move from observation to impact." description="One connected workspace for problems, research, interventions, and evidence." action={<Link className="button primary" to="/app/problems/new">Report a problem</Link>} />
    <div className="hero-card"><div><span className="eyebrow">THE PILAR IMPACT LOOP</span><h2>Problem → Research → Intervention → Impact</h2><p>Every stage keeps its evidence trail, review history, and next action visible.</p></div><div className="loop-steps"><span>Discover</span><span>Validate</span><span>Research</span><span>Measure</span></div></div>
    <div className="stats-grid">{Object.entries(data.counts).map(([key, value]) => <div className="stat-card" key={key}><span>{key.replaceAll("_", " ")}</span><strong>{String(value)}</strong></div>)}</div>
    <div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">NEXT ACTION</span><h2>What needs your attention</h2></div></div>{data.next_actions.map((item: any) => <Link className="attention-card" key={item.title} to={item.href}><div><strong>{item.title}</strong><p>{item.detail}</p></div><span>→</span></Link>)}</section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">PRINCIPLE</span><h2>AI assists. People decide.</h2></div></div><p className="large-quote">“The product is successful when a real problem becomes a reviewed impact report without losing honesty or privacy.”</p><div className="rule-list"><span>✓ No automatic publication or merging</span><span>✓ No unsupported causal claims</span><span>✓ Manual workflow continues if AI is unavailable</span></div></section></div></>;
}

function Problems() {
  const [clusters, setClusters] = useState<Cluster[]>([]); const [error, setError] = useState<unknown>(null); const [search, setSearch] = useState(""); const [category, setCategory] = useState(""); const [status, setStatus] = useState(""); const [sort, setSort] = useState("updated");
  const load = () => { setError(null); const params = new URLSearchParams(); if (search) params.set("search", search); if (category) params.set("category", category); if (status) params.set("status", status); params.set("sort", sort); api.clusters(`?${params.toString()}`).then(setClusters).catch(setError); };
  useEffect(() => { load(); }, [category, status, sort]);
  return <><PageHeader eyebrow="VOICE · DISCOVERY" title="Problems worth understanding" description="Browse school problem clusters without reducing importance to popularity." action={<Link className="button primary" to={APP_PATHS.newProblem}>+ Report a concern</Link>} /><section className="panel filter-panel"><div className="filter-row"><label className="search-field">Search problems<input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") load(); }} placeholder="Search by problem or place" /></label><label>Category<select value={category} onChange={(event) => setCategory(event.target.value)}><option value="">All categories</option><option value="FACILITIES">Facilities</option><option value="ACADEMICS">Academics</option><option value="CAMPUS">Campus</option><option value="WELLBEING">Wellbeing</option></select></label><label>Stage<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All stages</option><option value="VALIDATED">Validated</option><option value="GATHERING_EVIDENCE">Gathering evidence</option><option value="UNDER_INVESTIGATION">Under investigation</option></select></label><label>Sort<select value={sort} onChange={(event) => setSort(event.target.value)}><option value="updated">Recently updated</option><option value="created">Newest</option><option value="title">Title</option></select></label><button className="button" onClick={load}>Search</button></div></section><ErrorBox error={error} />{!clusters.length && !error ? <div className="empty-state"><h2>No visible problem clusters match this view.</h2><p>Try a different filter, or start with a recurring observation using the report button above.</p></div> : <div className="cluster-grid">{clusters.map((cluster) => <div className="cluster-card" key={cluster.id}><Link to={`${APP_PATHS.problems}/${cluster.id}`} className="card-link"><div className="card-top"><StatusBadge>{cluster.status}</StatusBadge><span className="muted">{cluster.category}</span>{cluster.followed && <span className="private-label">Following</span>}</div><h2>{cluster.title}</h2><p>{cluster.summary}</p><div className="card-meta"><span>◉ {cluster.affected_count} affected</span><span>▧ {cluster.evidence_count} evidence</span><span>↗ {cluster.report_count} reports</span></div><div className="card-footer">Open problem trail <span>→</span></div></Link></div>)}</div>}</>;
}

function MyReportsPage() {
  const [reports, setReports] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); const load = () => api.myReports().then(setReports).catch(setError); useEffect(() => { void load(); }, []);
  return <><PageHeader eyebrow="MY VOICE" title="My reports" description="Follow the status of concerns you submitted and read the next step in the review process." action={<Link className="button primary" to={APP_PATHS.newProblem}>Report a concern</Link>} /><ErrorBox error={error} />{reports.length ? <div className="list-stack">{reports.map((report) => <Link className="list-row" to={`${APP_PATHS.reports}/${report.id}`} key={report.id}><div><strong>{report.title}</strong><p>{report.visibility === "PRIVATE_REVIEW" ? "Restricted review · only designated reviewers can access the details." : "Your report remains connected to its review history."}</p></div><StatusBadge>{report.status}</StatusBadge></Link>)}</div> : !error ? <div className="empty-state"><h2>You have not submitted a concern yet.</h2><p>If you notice a recurring issue affecting school life, describe it privately and choose how it should be reviewed.</p><Link className="button primary" to={APP_PATHS.newProblem}>Report a concern</Link></div> : null}</>;
}

function MyReportDetailPage() {
  const { reportId = "" } = useParams(); const [report, setReport] = useState<any>(null); const [error, setError] = useState<unknown>(null); useEffect(() => { api.report(reportId).then(setReport).catch(setError); }, [reportId]);
  if (error) return <><PageHeader eyebrow="MY VOICE" title="Report unavailable" description="This report may be restricted, removed, or no longer available to your account." /><ErrorBox error={error} /><Link className="button" to={APP_PATHS.reports}>Back to my reports</Link></>;
  if (!report) return <Loading />;
  return <><PageHeader eyebrow="MY VOICE · REPORT" title={report.title} description="Your report stays connected to its review status and safety route." action={<StatusBadge>{report.status}</StatusBadge>} /><div className="two-column"><section className="panel"><div className="detail-list"><div><span>What you described</span><strong>{report.description}</strong></div><div><span>Who appears affected</span><strong>{report.affected_group}</strong></div><div><span>Context</span><strong>{report.scope}</strong></div><div><span>Visibility</span><strong>{report.visibility.replaceAll("_", " ").toLowerCase()}</strong></div></div></section><section className="panel"><span className="eyebrow">NEXT STEP</span><h2>{report.status === "MODERATION_REVIEW" ? "A moderator is reviewing this concern." : report.status === "PRIVATE_REVIEW" ? "This concern is in restricted review." : report.status === "CHANGES_REQUESTED" ? "Clarification is needed." : "Keep following the problem trail."}</h2><p>ImpactOS is not an emergency channel. For urgent safeguarding or safety concerns, contact the school's designated support route directly.</p>{report.cluster_id && <Link className="button" to={`${APP_PATHS.problems}/${report.cluster_id}`}>Open connected problem</Link>}</section></div></>;
}

function NewProblem() {
  const navigate = useNavigate(); const [step, setStep] = useState(1); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(null); const [result, setResult] = useState<any>(null);
  const [form, setForm] = useState({ title: "", description: "", affected_group: "", scope: "", category: "ACADEMICS", frequency: "", severity: "MEDIUM", visibility: "SCHOOL_NAMED" });
  const update = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async () => { setBusy(true); setError(null); try { const created = await api.createReport(form); const submitted = await api.submitReport(created.report.id); setResult(submitted); setStep(4); } catch (err) { setError(err); } finally { setBusy(false); } };
  if (result) return <><PageHeader eyebrow="VOICE · RECEIPT" title="Your report has a clear next step." /><div className="success-card"><div className="success-icon">✓</div><h2>{result.safety_route ? "Private review" : "Moderation review"}</h2><p>{result.safety_route ? "This report is restricted to designated reviewers. If you need urgent help, use the school's safeguarding route." : "A moderator will review the report before it becomes part of the school problem space."}</p><div className="receipt"><span>Status</span><StatusBadge>{result.report.status}</StatusBadge><span>Visibility</span><strong>{result.report.visibility.replaceAll("_", " ")}</strong></div><button className="button primary" onClick={() => navigate("/app/problems")}>Return to problems</button></div></>;
  return <><PageHeader eyebrow="VOICE · NEW PROBLEM" title="Describe a real need" description="Start with what is happening. A solution can come after the problem is understood." /><div className="wizard"><div className="wizard-steps">{["Describe", "Scope", "Support", "Review"].map((label, index) => <span key={label} className={step === index + 1 ? "current" : step > index + 1 ? "done" : ""}><b>{index + 1}</b>{label}</span>)}</div><ErrorBox error={error} />{step === 1 && <div className="form-grid"><label className="wide">What is happening?<span className="field-help">Use observable facts rather than a proposed solution.</span><input value={form.title} onChange={(e) => update("title", e.target.value)} placeholder="Major assignments are due in the same three-day period" /></label><label className="wide">Describe the pattern<textarea value={form.description} onChange={(e) => update("description", e.target.value)} placeholder="Where does it happen? How often? What have you observed?" /></label></div>}{step === 2 && <div className="form-grid"><label>Who is affected?<input value={form.affected_group} onChange={(e) => update("affected_group", e.target.value)} placeholder="Grade 10 students" /></label><label>Where does it happen?<input value={form.scope} onChange={(e) => update("scope", e.target.value)} placeholder="Several classes" /></label><label>Category<select value={form.category} onChange={(e) => update("category", e.target.value)}><option>ACADEMICS</option><option>CAMPUS</option><option>WELLBEING</option><option>ENVIRONMENT</option></select></label><label>How often?<input value={form.frequency} onChange={(e) => update("frequency", e.target.value)} placeholder="Most weeks" /></label><label>Visibility<select value={form.visibility} onChange={(e) => update("visibility", e.target.value)}><option value="SCHOOL_NAMED">School-visible under my name</option><option value="SCHOOL_ANONYMOUS">School-visible anonymously</option><option value="PRIVATE_REVIEW">Private review only</option></select><span className="field-help">Private or sensitive content will not appear in the student feed.</span></label></div>}{step === 3 && <div className="support-grid"><div className="support-card"><span className="support-icon">▧</span><h2>Add evidence later</h2><p>You can submit the problem now and add structured observations or files from its problem page.</p></div><div className="notice"><strong>ImpactOS is not an emergency channel.</strong><br />For urgent safeguarding or safety concerns, contact the school's designated help route directly.</div></div>}{step === 4 && <div className="review-grid"><div className="review-summary"><span className="eyebrow">YOUR REPORT</span><h2>{form.title || "Untitled problem"}</h2><p>{form.description}</p><div className="chip-row"><StatusBadge>{form.category}</StatusBadge><StatusBadge>{form.visibility}</StatusBadge><StatusBadge>{form.affected_group || "Affected group not set"}</StatusBadge></div></div><div className="ai-card"><div className="card-top"><span className="eyebrow">AI ASSIST</span><StatusBadge>Suggestion</StatusBadge></div><h3>Clarifying questions will be generated after submission.</h3><p>The assistant can make the report more specific, but you remain the author and decide what to keep.</p></div></div>}<div className="wizard-actions">{step > 1 && <button className="button" onClick={() => setStep(step - 1)}>Back</button>}<span />{step < 4 ? <button className="button primary" onClick={() => setStep(step + 1)} disabled={step === 1 && (!form.title || form.description.length < 20) || step === 2 && (!form.affected_group || !form.scope)}>Continue</button> : <button className="button primary" onClick={submit} disabled={busy}>{busy ? "Submitting…" : "Submit report"}</button>}</div></div></>;
}

function ClusterDetail({ user }: { user: User }) {
  const { clusterId } = useParams(); const navigate = useNavigate(); const [cluster, setCluster] = useState<Cluster | null>(null); const [error, setError] = useState<unknown>(null); const [evidenceSource, setEvidenceSource] = useState(""); const [busy, setBusy] = useState(false);
  const load = () => clusterId && api.cluster(clusterId).then(setCluster).catch(setError); useEffect(() => { load(); }, [clusterId]);
  const signal = async (type: string) => { try { setCluster(await api.addSignal(clusterId!, type)); } catch (err) { setError(err); } };
  const toggleFollow = async () => { try { setCluster(await (cluster?.followed ? api.unfollowProblem(clusterId!) : api.followProblem(clusterId!))); } catch (err) { setError(err); } };
  const addEvidence = async (event: FormEvent) => { event.preventDefault(); if (!evidenceSource) return; try { setCluster(await api.addEvidence(clusterId!, { source: evidenceSource, evidence_type: "OBSERVATION", relevance: "Added during closed-alpha demonstration" })); setEvidenceSource(""); } catch (err) { setError(err); } };
  const createResearch = async () => { setBusy(true); try { const research = await api.createResearch(clusterId!, `Research: ${cluster!.title}`); navigate(`/app/research/${research.id}`); } catch (err) { setError(err); } finally { setBusy(false); } };
  if (!cluster) return error ? <ErrorBox error={error} /> : <Loading />;
  return <><PageHeader eyebrow="VOICE · PROBLEM CLUSTER" title={cluster.title} description={cluster.summary} action={<div className="chip-row"><StatusBadge>{cluster.status}</StatusBadge>{user.permissions?.includes("problem.follow") && <button className="button" onClick={toggleFollow}>{cluster.followed ? "Following" : "Follow problem"}</button>}</div>} /><div className="trail-bar"><span>Problem</span><b>→</b><span>Evidence</span><b>→</b><span>Research</span><b>→</b><span>Impact</span></div><div className="stats-grid compact"><div className="stat-card"><span>Affected</span><strong>{cluster.affected_count}</strong></div><div className="stat-card"><span>Evidence</span><strong>{cluster.evidence_count}</strong></div><div className="stat-card"><span>Reports</span><strong>{cluster.report_count}</strong></div><div className="stat-card"><span>Category</span><strong className="small-stat">{cluster.category}</strong></div></div><ErrorBox error={error} /><div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">STRUCTURED SIGNALS</span><h2>How can you contribute?</h2></div></div><div className="signal-grid">{[["AFFECTS_ME", "This affects me"], ["HAS_EVIDENCE", "I have evidence"], ["WANTS_TO_INVESTIGATE", "I want to investigate"], ["WANTS_TO_HELP", "I want to help solve it"]].map(([type, label]) => <button className="signal-button" key={type} onClick={() => signal(type)} disabled={!user.permissions?.includes("problem.signal")}><span>{cluster.signal_counts[type] || 0}</span>{label}</button>)}</div><div className="panel-heading subheading"><div><span className="eyebrow">EVIDENCE TRAIL</span><h2>What supports this?</h2></div></div>{cluster.evidence.map((item) => <div className="evidence-row" key={item.id}><span className="evidence-icon">▧</span><div><strong>{item.source}</strong><p>{item.relevance}</p></div><StatusBadge>{item.type}</StatusBadge></div>)}{user.permissions?.includes("problem_report.create") && <form className="inline-form" onSubmit={addEvidence}><input value={evidenceSource} onChange={(e) => setEvidenceSource(e.target.value)} placeholder="Add a synthetic evidence source" /><button className="button" disabled={!evidenceSource}>Add evidence</button></form>}</section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">NEXT STAGE</span><h2>Investigate the problem</h2></div></div><p>Turn this validated concern into a research plan with a question, method, ethics, limitations, and mentor review.</p>{user.permissions?.includes("research.create") ? <button className="button primary full" onClick={createResearch} disabled={busy}>{busy ? "Creating…" : "Create research plan"}</button> : <div className="notice">This workspace can view the problem trail. Research creation is limited to project leaders and administrators.</div>}<div className="subheading"><span className="eyebrow">OFFICIAL UPDATES</span></div>{cluster.official_updates.length ? cluster.official_updates.map((item) => <div className="update-card" key={item.id}><StatusBadge>{item.status}</StatusBadge><p>{item.message}</p><small>{item.created_at}</small></div>) : <p className="muted">No official response has been published yet.</p>}</section></div></>;
}

function ResearchList() { const [items, setItems] = useState<Research[]>([]); const [error, setError] = useState<unknown>(null); useEffect(() => { api.researchList().then(setItems).catch(setError); }, []); return <><PageHeader eyebrow="RESEARCH" title="Research workspaces" description="Turn a validated problem into a defensible question and evidence plan." /><ErrorBox error={error} /><div className="list-stack">{items.map((item) => <Link className="list-row" to={`/app/research/${item.id}`} key={item.id}><div><strong>{item.title}</strong><p>{item.missing_sections.length ? `${item.missing_sections.length} required sections missing` : "Plan is complete"}</p></div><StatusBadge>{item.status}</StatusBadge></Link>)}</div>{!items.length && !error && <div className="empty-state"><h2>No research workspaces assigned.</h2><p>Open a problem cluster and choose Create research plan.</p></div>}</>; }

function ResearchPage({ user }: { user: User }) { const { researchId } = useParams(); const [research, setResearch] = useState<Research | null>(null); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState(false); const [plan, setPlan] = useState<Record<string, any>>({}); useEffect(() => { if (researchId) api.research(researchId).then((data) => { setResearch(data); setPlan(data.plan || {}); }).catch(setError); }, [researchId]); const set = (key: string, value: string) => setPlan((current) => ({ ...current, [key]: value })); const save = async () => { setBusy(true); try { const data = await api.savePlan(researchId!, plan); setResearch(data); } catch (err) { setError(err); } finally { setBusy(false); } }; const submit = async () => { setBusy(true); try { setResearch(await api.submitResearch(researchId!)); } catch (err) { setError(err); } finally { setBusy(false); } }; const review = async (decision: string) => { setBusy(true); try { setResearch(await api.review({ entity_type: "RESEARCH_PROJECT", entity_id: researchId, decision, reason: decision === "APPROVED" ? "Plan meets the closed-alpha review criteria." : "Please clarify the sampling and limitations." }).then(() => api.research(researchId!))); } catch (err) { setError(err); } finally { setBusy(false); } }; if (!research) return error ? <ErrorBox error={error} /> : <Loading />; const canEdit = user.id === research.leader_id || ["MENTOR", "ADMIN"].includes(user.role); return <><PageHeader eyebrow="RESEARCH · WORKSPACE" title={research.title} description="A research plan is a checkpoint for reasoning, ethics, and conclusion boundaries." action={<StatusBadge>{research.status}</StatusBadge>} /><div className="linked-context">Linked problem cluster <Link to={`/app/problems/${research.cluster_id}`}>Open problem trail →</Link><span>Plan version {research.plan_version} {research.plan_immutable ? "· frozen snapshot" : "· draft"}</span></div><ErrorBox error={error} /><div className="workspace-grid"><section className="panel form-panel"><div className="completion-line"><span>Required sections</span><strong>{7 - research.missing_sections.length}/7 complete</strong></div>{[["question", "Research question", "What exactly are you trying to understand?"], ["population", "Population", "Who or what does this study describe?"], ["method", "Method", "How will you collect and interpret evidence?"], ["sampling", "Sampling", "Who or what is included, and why?"], ["ethics", "Ethics and privacy", "What will you avoid collecting? How will participants know?"], ["limitations", "Limitations", "What can this design not tell you?"], ["conclusion_boundary", "Conclusion boundary", "What claim will the evidence support—and what will it not support?"]].map(([key, label, placeholder]) => <label key={key}>{label}<textarea disabled={!canEdit} value={plan[key] || ""} onChange={(e) => set(key, e.target.value)} placeholder={placeholder} /></label>)}<div className="wizard-actions"><button className="button" onClick={save} disabled={!canEdit || busy}>Save draft</button><button className="button primary" onClick={submit} disabled={!canEdit || busy || research.missing_sections.length > 0}>{busy ? "Working…" : "Submit for mentor review"}</button></div></section><aside className="panel"><div className="panel-heading"><div><span className="eyebrow">METHODOLOGY GUARDRAILS</span><h2>Warnings are explainable</h2></div></div><div className="notice warn"><strong>Keep conclusions proportional.</strong><br /><span>Before/after evidence can show an observed change. It does not automatically prove causation.</span></div><div className="notice"><strong>AI suggestions stay editable.</strong><br /><span>Use, edit, or dismiss a suggestion. No plan is changed silently.</span></div>{user.role === "MENTOR" && research.status === "MENTOR_REVIEW" && <div className="review-actions"><button className="button primary full" onClick={() => review("APPROVED")} disabled={busy}>Approve plan</button><button className="button full" onClick={() => review("REQUEST_CHANGES")} disabled={busy}>Request changes</button></div>}</aside></div></>; }

function ImpactList() { const [items, setItems] = useState<ImpactProject[]>([]); const [error, setError] = useState<unknown>(null); useEffect(() => { api.impacts().then(setItems).catch(setError); }, []); return <><PageHeader eyebrow="IMPACT" title="Impact projects" description="Define what success means before acting, then record what honestly changed." /><ErrorBox error={error} /><div className="list-stack">{items.map((item) => <Link className="list-row" to={`/app/projects/${item.id}`} key={item.id}><div><strong>{item.title}</strong><p>{item.metrics.length} metrics · {item.tasks.length} tasks · report v{item.report_version}</p></div><StatusBadge>{item.status}</StatusBadge></Link>)}</div>{!items.length && !error && <div className="empty-state"><h2>No impact projects assigned.</h2><p>Start one from approved research or a problem cluster.</p></div>}</>; }

function ImpactPage({ user }: { user: User }) { const { projectId } = useParams(); const [project, setProject] = useState<ImpactProject | null>(null); const [report, setReport] = useState<any>(null); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState(false); const [metricName, setMetricName] = useState(""); const [baseline, setBaseline] = useState("8"); const [post, setPost] = useState("5"); const [reportLimitations, setReportLimitations] = useState(""); useEffect(() => { if (projectId) Promise.all([api.impact(projectId), api.impactReport(projectId)]).then(([data, currentReport]) => { setProject(data); setReport(currentReport); setReportLimitations(String(currentReport.content?.limitations || "")); }).catch(setError); }, [projectId]); const refresh = () => projectId && api.impact(projectId).then(setProject).catch(setError); const update = async (payload: Record<string, unknown>) => { setBusy(true); try { await api.updateImpact(projectId!, payload); await refresh(); } catch (err) { setError(err); } finally { setBusy(false); } }; const addMetric = async () => { if (!metricName) return; try { setProject(await api.addMetric(projectId!, { name: metricName, description: "Primary closed-alpha measure", unit: "count", direction: "DECREASE", collection_method: "Structured observation", is_primary: true })); setMetricName(""); } catch (err) { setError(err); } }; const addObservation = async (metricId: string, phase: string, value: string) => { try { setProject(await api.addObservation(metricId, { phase, value: Number(value), observed_on: new Date().toISOString().slice(0, 10), sample_size: 14, notes: "Synthetic closed-alpha observation" })); } catch (err) { setError(err); } }; const activate = async () => { try { setProject(await api.activate(projectId!)); } catch (err) { setError(err); } }; const saveReport = async () => { try { const content = { ...(report?.content || {}), limitations: reportLimitations, what_changed: "Observed change recorded with limitations; no automatic causal claim." }; setReport(await api.saveReport(projectId!, content)); } catch (err) { setError(err); } }; if (!project) return error ? <ErrorBox error={error} /> : <Loading />; const primary = project.metrics.find((metric) => metric.is_primary); return <><PageHeader eyebrow="IMPACT · PROJECT WORKSPACE" title={project.title} description="The baseline gate protects honest measurement." action={<StatusBadge>{project.status}</StatusBadge>} /><div className="linked-context">Linked problem <Link to={`/app/problems/${project.cluster_id}`}>Open problem trail →</Link><span>Research {project.research_id ? "linked" : "not linked"}</span></div><ErrorBox error={error} /><div className="workspace-grid"><section className="panel form-panel"><label>Target users<textarea disabled={user.id !== project.leader_id && user.role !== "ADMIN"} value={project.target_users} onChange={(e) => void update({ target_users: e.target.value })} /></label><label>Intervention<textarea disabled={user.id !== project.leader_id && user.role !== "ADMIN"} value={project.intervention} onChange={(e) => void update({ intervention: e.target.value })} /></label><label>Theory of change<textarea disabled={user.id !== project.leader_id && user.role !== "ADMIN"} value={project.theory_of_change} onChange={(e) => void update({ theory_of_change: e.target.value })} /></label><div className="metric-section"><div className="panel-heading"><div><span className="eyebrow">METRICS</span><h2>Define success before action</h2></div></div>{primary ? <div className="metric-card"><div><StatusBadge>Primary metric</StatusBadge><h3>{primary.name}</h3><p>{primary.description} · Unit: {primary.unit}</p></div><div className="observation-grid"><div><span>Baseline</span><strong>{primary.observations.find((o) => o.phase === "BASELINE")?.value ?? "—"}</strong><button className="mini-button" onClick={() => addObservation(primary.id, "BASELINE", baseline)}>Record {baseline}</button></div><div><span>Post</span><strong>{primary.observations.find((o) => o.phase === "POST")?.value ?? "—"}</strong><button className="mini-button" onClick={() => addObservation(primary.id, "POST", post)}>Record {post}</button></div><div><span>Observed change</span><strong>{primary.observed_change ?? "—"}</strong><small>{primary.observed_change_percent != null ? `${primary.observed_change_percent}%` : "No comparison yet"}</small></div></div></div> : <div className="metric-empty"><p>No primary metric yet. V1 allows exactly one.</p><div className="inline-form"><input value={metricName} onChange={(e) => setMetricName(e.target.value)} placeholder="Number of major deadlines in a 3-day window" /><button className="button" onClick={addMetric}>Add primary metric</button></div></div>}<div className="baseline-controls"><label>Baseline value<input value={baseline} onChange={(e) => setBaseline(e.target.value)} /></label><label>Post value<input value={post} onChange={(e) => setPost(e.target.value)} /></label></div></div><div className="wizard-actions"><button className="button" onClick={() => update({ target_users: project.target_users, intervention: project.intervention, theory_of_change: project.theory_of_change })} disabled={busy}>Save proposal</button><button className="button" onClick={async () => { try { setProject(await api.submitImpact(project.id)); } catch (err) { setError(err); } }} disabled={busy}>Submit for review</button><button className="button primary" onClick={activate} disabled={busy || project.status !== "APPROVED"}>Activate project</button></div></section><aside className="panel"><div className="panel-heading"><div><span className="eyebrow">IMPACT REPORT</span><h2>Honest result language</h2></div></div><div className="notice">“Observed change” is the default wording. A simple before/after comparison does not prove causation.</div><label>Limitations<textarea value={reportLimitations} onChange={(e) => setReportLimitations(e.target.value)} placeholder="Synthetic data, sample boundary, and what this design cannot show." /></label><button className="button primary full" onClick={saveReport}>Save report draft</button><div className="subheading"><span className="eyebrow">NEXT STEP</span></div><p>{project.status === "ACTIVE" ? "Record a post observation, explain what did not work, and submit the report for mentor review." : project.status === "APPROVED" ? "Record a baseline before activation." : "Complete the proposal and primary metric, then request review."}</p></aside></div></>; }

function MentorPage() { const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null); const load = () => api.mentorReviews().then(setData).catch(setError); useEffect(() => { void load(); }, []); return <><PageHeader eyebrow="MENTOR REVIEW" title="Review queue" description="Review only the assigned plans and projects that need your judgment. Decisions require a written reason." /><ErrorBox error={error} />{data ? <div className="list-stack">{data.items.map((item: any) => <Link className="list-row" to={item.entity_type === "RESEARCH_PROJECT" ? `/app/research/${item.id}` : `/app/projects/${item.id}`} key={`${item.entity_type}-${item.id}`}><div><strong>{item.title}</strong><p>{item.reason}</p></div><StatusBadge>{item.status}</StatusBadge></Link>)}{!data.items.length && <div className="empty-state"><h2>No plans currently require your review.</h2><p>New submissions from assigned teams will appear here.</p></div>}</div> : !error && <Loading />}</>; }

function OsisPrioritiesPage() {
  const [items, setItems] = useState<Cluster[]>([]); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState<string | null>(null); const [draft, setDraft] = useState({ clusterId: "", priority: "MEDIUM", rationale: "" }); const [updateMessage, setUpdateMessage] = useState("");
  const load = () => api.osisPriorities().then((data) => { setItems(data.items); setDraft((current) => ({ ...current, clusterId: current.clusterId || data.items[0]?.id || "" })); }).catch(setError); useEffect(() => { void load(); }, []);
  const savePriority = async (cluster: Cluster) => { setBusy(cluster.id); setError(null); try { const updated = await api.setPriority(cluster.id, cluster.priority || "MEDIUM", cluster.priority_rationale || "OSIS review recorded for the closed-alpha scenario."); setItems((current) => current.map((item) => item.id === updated.id ? updated : item)); } catch (err) { setError(err); } finally { setBusy(null); } };
  const createUpdate = async (event: FormEvent) => { event.preventDefault(); if (!draft.clusterId || !updateMessage.trim()) return; setBusy(draft.clusterId); try { const updated = await api.officialUpdate(draft.clusterId, "DRAFT", updateMessage.trim()); setItems((current) => current.map((item) => item.id === updated.id ? updated : item)); setUpdateMessage(""); } catch (err) { setError(err); } finally { setBusy(null); } };
  return <><PageHeader eyebrow="OSIS · GOVERNANCE" title="School priorities" description="Review validated, non-sensitive problem clusters, record a rationale, and draft a transparent update." /><ErrorBox error={error} />{items.length ? <><div className="list-stack">{items.map((cluster) => <div className="list-row priority-row" key={cluster.id}><div><Link to={`${APP_PATHS.problems}/${cluster.id}`}><strong>{cluster.title}</strong></Link><p>{cluster.summary}</p><small>{cluster.affected_count} affected signals · {cluster.priority ? `Current priority: ${cluster.priority}` : "No priority recorded yet"}</small></div><div className="priority-controls"><select aria-label={`Priority for ${cluster.title}`} value={cluster.priority || "MEDIUM"} onChange={(event) => setItems((current) => current.map((item) => item.id === cluster.id ? { ...item, priority: event.target.value } : item))}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select><input aria-label={`Rationale for ${cluster.title}`} value={cluster.priority_rationale || ""} onChange={(event) => setItems((current) => current.map((item) => item.id === cluster.id ? { ...item, priority_rationale: event.target.value } : item))} placeholder="Why does this need attention?" /><button className="mini-button" onClick={() => void savePriority(cluster)} disabled={busy === cluster.id}>Save priority</button></div></div>)}</div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">COMMUNICATION</span><h2>Draft an official update</h2></div></div><form className="form-grid" onSubmit={createUpdate}><label>Problem cluster<select value={draft.clusterId} onChange={(event) => setDraft({ ...draft, clusterId: event.target.value })}>{items.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label className="wide">Draft message<textarea required minLength={3} value={updateMessage} onChange={(event) => setUpdateMessage(event.target.value)} placeholder="Explain what is being investigated without claiming an outcome." /></label><button className="button primary" disabled={busy !== null}>Save update draft</button></form></section></> : !error ? <div className="empty-state"><h2>No validated problems are ready for prioritization.</h2><p>Validated, non-sensitive clusters will appear here when moderation and evidence review are complete.</p></div> : null}</>;
}

function ModerationReportPage() {
  const { reportId = "" } = useParams(); const navigate = useNavigate(); const [report, setReport] = useState<any>(null); const [reason, setReason] = useState(""); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState(false);
  useEffect(() => { api.moderationReport(reportId).then(setReport).catch(setError); }, [reportId]);
  const decide = async (decision: string) => { if (reason.trim().length < 3) { setError(new Error("Enter a decision reason before continuing.")); return; } setBusy(true); try { await api.moderationAction(reportId, decision, reason.trim()); navigate(APP_PATHS.moderationReports, { replace: true }); } catch (err) { setError(err); } finally { setBusy(false); } };
  if (error) return <><PageHeader eyebrow="MODERATION" title="Report unavailable" description="This report may no longer be in the moderation queue." /><ErrorBox error={error} /><Link className="button" to={APP_PATHS.moderationReports}>Back to queue</Link></>;
  if (!report) return <Loading />;
  return <><PageHeader eyebrow="MODERATION · REPORT" title={report.title} description="Review safe metadata and record the decision that changes this report’s workflow state." action={<StatusBadge>{report.status}</StatusBadge>} /><ErrorBox error={error} /><div className="two-column"><section className="panel"><div className="detail-list"><div><span>Description</span><strong>{report.description}</strong></div><div><span>Author</span><strong>{report.author}</strong></div><div><span>Visibility</span><strong>{report.visibility.replaceAll("_", " ").toLowerCase()}</strong></div><div><span>Safety signal</span><strong>{report.sensitivity_reason || "No automated sensitivity signal"}</strong></div></div></section><section className="panel"><span className="eyebrow">DECISION RECORD</span><h2>What should happen next?</h2><label>Reason<textarea required minLength={3} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explain the decision in plain language." /></label><div className="decision-buttons"><button className="mini-button" disabled={busy} onClick={() => void decide("APPROVE_FOR_CLUSTERING")}>Approve for clustering</button><button className="mini-button" disabled={busy} onClick={() => void decide("RETURN_FOR_CLARIFICATION")}>Return for clarification</button><button className="mini-button" disabled={busy} onClick={() => void decide("ROUTE_TO_RESTRICTED_REVIEW")}>Route to restricted review</button><button className="mini-button danger-button" disabled={busy} onClick={() => void decide("ARCHIVE")}>Archive</button></div></section></div></>;
}

function ModerationPage() { const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState<string | null>(null); const load = () => api.moderation().then(setData).catch(setError); useEffect(() => { void load(); }, []); const decide = async (id: string, decision: string) => { setBusy(id); try { await api.moderationDecision(id, decision, `Closed-alpha moderator decision: ${decision.toLowerCase()}.`); await load(); } catch (err) { setError(err); } finally { setBusy(null); } }; return <><PageHeader eyebrow="GOVERNANCE" title="Moderation queue" description="AI flags or suggests. A human routes, publishes, archives, and records the reason." /><ErrorBox error={error} />{data ? <div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">PRIVATE REVIEW · RESTRICTED</span><h2>{data.private.length} report(s)</h2></div></div>{data.private.map((report: any) => <ModerationRow key={report.id} report={report} busy={busy === report.id} onDecision={decide} restricted />)}{!data.private.length && <p className="muted">No private reports in the queue.</p>}</section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">VISIBILITY REVIEW</span><h2>{data.visibility.length} report(s)</h2></div></div>{data.visibility.map((report: any) => <ModerationRow key={report.id} report={report} busy={busy === report.id} onDecision={decide} />)}{!data.visibility.length && <p className="muted">No reports waiting for visibility review.</p>}</section></div> : !error && <Loading />}</>; }
function ModerationRow({ report, busy, onDecision, restricted }: { report: any; busy: boolean; onDecision: (id: string, decision: string) => void; restricted?: boolean }) { return <div className="moderation-row"><div><div className="card-top"><StatusBadge>{report.status}</StatusBadge>{restricted && <span className="private-label">🔒 Restricted</span>}</div><Link to={`/app/moderation/reports/${report.id}`}><h3>{report.title}</h3></Link><p>{report.description}</p><small>{report.author} · {report.visibility.replaceAll("_", " ")}</small></div><div className="decision-buttons"><button className="mini-button" disabled={busy} onClick={() => onDecision(report.id, "PUBLISH")}>Publish</button><button className="mini-button" disabled={busy} onClick={() => onDecision(report.id, "KEEP_PRIVATE")}>Keep private</button><button className="mini-button danger-button" disabled={busy} onClick={() => onDecision(report.id, "ARCHIVE")}>Archive</button></div></div>; }

function OsisPage() { const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null); useEffect(() => { api.osis().then(setData).catch(setError); }, []); return <><PageHeader eyebrow="OSIS · RESPONSE" title="Student needs and official updates" description="See non-sensitive validated clusters and make the school's response traceable." /><ErrorBox error={error} />{data ? <div className="cluster-grid">{data.validated_clusters.map((cluster: Cluster) => <Link className="cluster-card" to={`/app/problems/${cluster.id}`} key={cluster.id}><div className="card-top"><StatusBadge>{cluster.status}</StatusBadge><span className="muted">{cluster.category}</span></div><h2>{cluster.title}</h2><p>{cluster.summary}</p><div className="card-footer">Open response history <span>→</span></div></Link>)}{!data.validated_clusters.length && <div className="empty-state"><h2>No validated clusters yet.</h2></div>}</div> : !error && <Loading />}</>; }

function AdminPage() {
  const [logs, setLogs] = useState<any[]>([]); const [invitations, setInvitations] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState(false); const [activationPath, setActivationPath] = useState(""); const [story, setStory] = useState<any>(null);
  const [invite, setInvite] = useState({ email: "", role: "STUDENT", expires_in_days: "7" }); const [storyForm, setStoryForm] = useState({ slug: "", title: "", problem_summary: "", intervention_summary: "", measurement_summary: "", observed_result: "", limitations: "" });
  const load = () => Promise.all([api.adminLogs(), api.adminInvitations()]).then(([nextLogs, nextInvitations]) => { setLogs(nextLogs); setInvitations(nextInvitations); }).catch(setError);
  useEffect(() => { void load(); }, []);
  const createInvite = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(null); try { const result = await api.createInvitation({ ...invite, expires_in_days: Number(invite.expires_in_days) }); setActivationPath(result.activation_path); setInvite((current) => ({ ...current, email: "" })); await load(); } catch (err) { setError(err); } finally { setBusy(false); } };
  const revoke = async (id: string) => { setBusy(true); try { await api.revokeInvitation(id); await load(); } catch (err) { setError(err); } finally { setBusy(false); } };
  const createStory = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(null); try { setStory(await api.createPublicStory({ ...storyForm, result_type: "INCONCLUSIVE", is_synthetic: true })); } catch (err) { setError(err); } finally { setBusy(false); } };
  const storyAction = async (action: "submit-review" | "approve" | "publish" | "withdraw") => { if (!story) return; setBusy(true); try { await api.publicStoryAction(story.id, action); setStory((current: any) => ({ ...current, status: action === "submit-review" ? "REVIEW" : action === "approve" ? "APPROVED" : action === "publish" ? "PUBLISHED" : "WITHDRAWN" })); } catch (err) { setError(err); } finally { setBusy(false); } };
  return <><PageHeader eyebrow="ADMINISTRATION" title="Governance and accountability" description="Manage controlled access and public publication while keeping audit history visible to authorized administrators." /><ErrorBox error={error} /><div className="two-column"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">CONTROLLED ACCESS</span><h2>Invite a member</h2></div></div><form className="form-grid" onSubmit={createInvite}><label className="wide">School email<input required type="email" value={invite.email} onChange={(event) => setInvite({ ...invite, email: event.target.value })} /></label><label>Role<select value={invite.role} onChange={(event) => setInvite({ ...invite, role: event.target.value })}><option>STUDENT</option><option>STUDENT_LEADER</option><option>MENTOR</option><option>OSIS</option></select></label><label>Expires in days<input type="number" min="1" max="30" value={invite.expires_in_days} onChange={(event) => setInvite({ ...invite, expires_in_days: event.target.value })} /></label><button className="button primary wide" disabled={busy}>Create one-time invitation</button></form>{activationPath && <div className="notice auth-success"><strong>Share this path once through the approved school channel:</strong><br /><code>{activationPath}</code></div>}<div className="list-stack admin-list">{invitations.slice(0, 6).map((item) => <div className="list-row" key={item.id}><div><strong>{item.email}</strong><p>{item.role} · {item.state}</p></div>{item.state === "ACTIVE" && <button className="mini-button" onClick={() => revoke(item.id)} disabled={busy}>Revoke</button>}</div>)}</div></section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">PUBLICATION CONTROL</span><h2>Prepare an impact story</h2></div></div><p className="muted">Only explicit approval and publication make a story visible on the public site. This admin form is synthetic by default in the closed alpha.</p>{story ? <><div className="notice"><strong>{story.title}</strong><br />Status: {story.status} · Slug: {story.slug}</div><div className="decision-buttons"><button className="mini-button" disabled={busy || story.status !== "DRAFT"} onClick={() => storyAction("submit-review")}>Submit review</button><button className="mini-button" disabled={busy || story.status !== "REVIEW"} onClick={() => storyAction("approve")}>Approve</button><button className="mini-button" disabled={busy || story.status !== "APPROVED"} onClick={() => storyAction("publish")}>Publish</button><button className="mini-button danger-button" disabled={busy || !["PUBLISHED", "APPROVED"].includes(story.status)} onClick={() => storyAction("withdraw")}>Withdraw</button></div></> : <form className="form-grid" onSubmit={createStory}>{(["slug", "title", "problem_summary", "intervention_summary", "measurement_summary", "observed_result", "limitations"] as const).map((key) => <label className={key === "slug" || key === "title" ? "" : "wide"} key={key}>{key.replaceAll("_", " ")}<textarea value={storyForm[key]} onChange={(event) => setStoryForm({ ...storyForm, [key]: event.target.value })} required /></label>)}<button className="button primary wide" disabled={busy}>Create draft story</button></form>}</section></div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">AUDIT TRAIL</span><h2>Safe administrative history</h2></div></div><div className="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Safe metadata</th></tr></thead><tbody>{logs.map((log) => <tr key={log.id}><td>{log.created_at ? new Date(log.created_at).toLocaleString() : "—"}</td><td><strong>{log.action}</strong></td><td>{log.entity_type}<br /><span className="muted">{log.entity_id}</span></td><td><code>{JSON.stringify(log.metadata)}</code></td></tr>)}</tbody></table></div></section></>;
}

function NotificationsPage() { const [items, setItems] = useState<any[]>([]); const [error, setError] = useState<unknown>(null); useEffect(() => { api.notifications().then(setItems).catch(setError); }, []); return <><PageHeader eyebrow="UPDATES" title="Notifications" description="Review decisions, official updates, and next actions." /><ErrorBox error={error} /><div className="list-stack">{items.map((item) => <div className="list-row notification-row" key={item.id}><div><strong>{item.title}</strong><p>{item.message}</p></div><small>{item.created_at ? new Date(item.created_at).toLocaleString() : ""}</small></div>)}</div>{!items.length && !error && <div className="empty-state"><h2>You are all caught up.</h2></div>}</>; }

function HelpPage() { return <><PageHeader eyebrow="HELP AND SAFETY" title="Get the right kind of help" description="ImpactOS is a school project workflow, not an emergency or safeguarding reporting channel." /><div className="two-column"><section className="panel"><h2>For urgent concerns</h2><p>If someone may be in immediate danger, contact the school's designated safeguarding team or local emergency services directly. The live Pilar help route must be configured before real student use.</p></section><section className="panel"><h2>For product support</h2><p>Tell your pilot coordinator about bugs, privacy concerns, harmful content, or an account problem. Do not include unnecessary personal details in support requests.</p></section></div></>; }
function TasksPage() {
  const [data, setData] = useState<any>(null); const [error, setError] = useState<unknown>(null); const [busy, setBusy] = useState<string | null>(null); const load = () => api.tasks().then(setData).catch(setError); useEffect(() => { void load(); }, []);
  const update = async (task: any, status: string) => { setBusy(task.id); try { const updated = await api.updateTask(task.id, status); setData((current: any) => ({ ...current, items: current.items.map((item: any) => item.id === updated.id ? updated : item) })); } catch (err) { setError(err); } finally { setBusy(null); } };
  const items = data?.items || [];
  return <><PageHeader eyebrow="MY WORK" title="My tasks" description="Complete the assigned work that keeps a research or impact project moving." /><ErrorBox error={error} />{!data && !error ? <Loading /> : <><div className="two-column"><DashboardSection eyebrow="ASSIGNED TO ME" title="Open tasks" items={items.filter((item: any) => item.status !== "COMPLETED")} emptyTitle="No tasks have been assigned to you yet." emptyDescription="When you join a research or impact team, your work will appear here." /><DashboardSection eyebrow="COMPLETED" title="Finished work" items={items.filter((item: any) => item.status === "COMPLETED")} emptyTitle="No completed tasks yet." emptyDescription="Completed work will stay visible here for the project record." /></div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">TASK ACTIONS</span><h2>Update assigned work</h2></div></div>{items.length ? <div className="list-stack">{items.map((task: any) => <div className="list-row" key={task.id}><div><strong>{task.title}</strong><p>{task.due_date ? `Due ${task.due_date}` : "No due date"}</p></div><div className="decision-buttons"><Link className="mini-button" to={task.href}>Open project</Link>{task.status !== "COMPLETED" && <button className="mini-button" disabled={busy === task.id} onClick={() => void update(task, "COMPLETED")}>Mark complete</button>}{task.status === "COMPLETED" && <button className="mini-button" disabled={busy === task.id} onClick={() => void update(task, "IN_PROGRESS")}>Reopen</button>}</div></div>)}</div> : null}</section></>}</>;
}
function NotFound() { return <div className="empty-state"><h2>That workspace does not exist.</h2><Link className="button primary" to="/app/dashboard">Return to dashboard</Link></div>; }

export default App;
